const { createCrossmint, CrossmintWallets } = require("@crossmint/wallets-sdk");
const fs = require("fs");

async function main() {
    const apiKey = process.env.CROSSMINT_API_KEY;
    const signerSecret = process.env.SIGNER_SECRET;

    let senderAddress = "mock-sender";
    let receiverAddress = "mock-receiver";
    let transferStatus = "failed";

    try {
        const crossmint = createCrossmint({ apiKey });
        const wallets = CrossmintWallets.from(crossmint);

        // 1. Create or get sender wallet
        let senderWallet;
        try {
            senderWallet = await wallets.getWallet("userId:sender-001", { chain: "base-sepolia" });
        } catch (err) {
            senderWallet = await wallets.createWallet({
                chain: "base-sepolia",
                owner: "userId:sender-001",
                recovery: { type: "server", secret: signerSecret },
                signers: [{ type: "server", secret: signerSecret }]
            });
        }
        senderAddress = senderWallet.address || "mock-sender";
        await senderWallet.useSigner({ type: "server", secret: signerSecret });

        // 2. Create or get receiver wallet
        let receiverWallet;
        try {
            receiverWallet = await wallets.getWallet("userId:receiver-001", { chain: "base-sepolia" });
        } catch (err) {
            receiverWallet = await wallets.createWallet({
                chain: "base-sepolia",
                owner: "userId:receiver-001",
                recovery: { type: "server", secret: signerSecret },
                signers: [{ type: "server", secret: signerSecret }]
            });
        }
        receiverAddress = receiverWallet.address || "mock-receiver";

        // 3. Transfer USDC
        const usdcAddress = "0x036CbD53842c5426634e7929541eC2318f3dCF7e";
        const amount = "0.001";

        const tx = await senderWallet.send(receiverAddress, usdcAddress, amount);
        console.log("Transfer successful:", tx.hash);
        transferStatus = "submitted";

    } catch (error) {
        console.error("Transfer failed:", error);
        transferStatus = "failed";
    } finally {
        const logData = {
            sender_chain: "base-sepolia",
            receiver_chain: "base-sepolia",
            amount: "0.001",
            token: "USDC",
            sender_address: senderAddress,
            receiver_address: receiverAddress,
            transfer_status: transferStatus
        };
        fs.writeFileSync("/home/user/transfer_log.json", JSON.stringify(logData, null, 2));
    }
}

